SELECT symbol, open_time, UNIX_TIMESTAMP(open_time) AS open_epoch, open_price, high_price, low_price, close_price, volume, number_of_trades, closed, ingestion_source FROM crypto_ai.candle WHERE interval_code='1m' AND ((symbol='EGLDUSDT' AND open_time BETWEEN FROM_UNIXTIME(1791747480) AND FROM_UNIXTIME(1791747840)) OR (symbol='ACEUSDT' AND open_time BETWEEN FROM_UNIXTIME(1791788100) AND FROM_UNIXTIME(1791788760))) ORDER BY symbol, open_time LIMIT 40;